const TYPES_CLASS = {
    error: 'notification-danger',
    warning: 'notification-warning',
    info: 'notification-info',
    success: 'notification-success',
};

const CLASSES = {
    NOTIFICATION: 'notification',
    NOTIFICATION_IN: 'notification--in',
